{"sql": "-- Check if lap 0 and lap 1 have the same positions
WITH p0 AS (
    SELECT race_id, driver_id, position FROM lap_positions WHERE CAST(lap AS INTEGER) = 0 AND lap_type = 'Race'
),
p1 AS (
    SELECT race_id, driver_id, position FROM lap_positions WHERE CAST(lap AS INTEGER) = 1 AND lap_type = 'Race'
)
SELECT COUNT(*) FROM p0 JOIN p1 ON p0.race_id = p1.race_id AND p0.driver_id = p1.driver_id AND p0.position != p1.position LIMIT 10"}
